def calc_trend(values):
    if len(values) < 2 or values[0] == 0:
        return 0
    return ((values[-1] - values[0]) / values[0]) * 100

results = []
for name, data in clients.items():
    nps_trend = calc_trend(data["nps"])
    csat_trend = calc_trend(data["csat"])
    login_trend = calc_trend(data["login"])

    risk_score = 0
    # NPS Risk
    if data["nps"][-1] <= 3:
        risk_score += 25
    elif data["nps"][-1] <= 6:
        risk_score += 15
    elif data["nps"][-1] <= 8:
        risk_score += 5
    if nps_trend < -20:
        risk_score += 10

    # CSAT Risk
    if data["csat"][-1] <= 2.0:
        risk_score += 25
    elif data["csat"][-1] <= 3.0:
        risk_score += 15
    elif data["csat"][-1] <= 3.5:
        risk_score += 5
    if csat_trend < -15:
        risk_score += 10

    # Login Risk
    if data["login"][-1] < 10:
        risk_score += 20
    elif data["login"][-1] < 20:
        risk_score += 10
    elif data["login"][-1] < 30:
        risk_score += 5
    if login_trend < -30:
        risk_score += 10

    # Lifecycle
    if data["lifecycle"] == "At Risk":
        risk_score += 15
    elif data["lifecycle"] == "Onboarding":
        risk_score += 5
    elif data["lifecycle"] == "Renewal":
        risk_score += 8

    # Renewal
    if data["renewal"] == "Medium":
        risk_score += 8

    results.append({
        "name": name,
        "risk_score": risk_score,
        "nps_trend": nps_trend,
        "csat_trend": csat_trend,
        "login_trend": login_trend,
        "current_nps": data["nps"][-1],
        "current_csat": data["csat"][-1],
        "current_login": data["login"][-1],
        "data": data
    })

results.sort(key=lambda x: x["risk_score"], reverse=True)

for i, r in enumerate(results, 1):
    print(f"{i}. {r['name']} - RISK SCORE: {r['risk_score']}/100")
    print(f"   Industry: {r['data']['industry']} | ARR: ${r['data']['arr']:,} | Tier: {r['data']['tier']}")
    print(f"   Churn Risk: {r['data']['churn_risk']} | Lifecycle: {r['data']['lifecycle']}")
    print(f"   CURRENT METRICS (Jan 2026):")
    print(f"   - Login: {r['current_login']}/month (Trend: {r['login_trend']:+.1f}%)")
    print(f"   - NPS: {r['current_nps']}/10 (Trend: {r['nps_trend']:+.1f}%)")
    print(f"   - CSAT: {r['current_csat']:.2f}/5.0 (Trend: {r['csat_trend']:+.1f}%)")
    print("   WARNING INDICATORS:")
    warnings = []
    if r['nps_trend'] < -20:
        warnings.append("⚠️ NPS Regression")
    if r['csat_trend'] < -15:
        warnings.append("⚠️ CSAT Deterioration")
    if r['login_trend'] < -30:
        warnings.append("⚠️ Severe Login Drop")
    if r['current_nps'] <= 6:
        warnings.append(f"⚠️ Low NPS ({r['current_nps']}/10)")
    if r['current_csat'] <= 3.0:
        warnings.append(f"⚠️ Critical CSAT ({r['current_csat']:.2f}/5.0)")
    if r['current_login'] < 15:
        warnings.append(f"⚠️ Low Login ({r['current_login']}/month)")
    if r['data']['lifecycle'] == "At Risk":
        warnings.append("⚠️ At Risk Lifecycle")
    if warnings:
        for w in warnings:
            print(f"   {w}")
    else:
        print("   ✓ No critical warnings")
    print("-" * 80)
    print()

print("SUMMARY")
print("=" * 80)
total_arr = sum(r['data']['arr'] for r in results)
